"use client";

import {
  useDeferredValue,
  useEffect,
  useEffectEvent,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
} from "react";
import { AnimatePresence, motion, type Variants } from "motion/react";

import { cn } from "../lib/cn";
import { SpinnerIcon } from "../spinner/spinner";
import { useControllable } from "../hooks/use-controllable";
import { isImeComposing } from "../lib/ime";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { duration, spring } from "../motion/tokens";
import { exitTransition } from "../motion/presets";
import { Dialog, DialogClose, DialogContent, DialogTitle, DialogTrigger } from "../dialog/dialog";
import { Kbd, KbdShortcut, useShortcutPlatform } from "../kbd/kbd";
import { useCommandShortcut } from "./use-command-shortcut";
import { pageSize } from "../lib/page-size";
import { shouldVirtualize, useVirtualWindow } from "../hooks/use-virtual-window";

import {
  type CommandItem,
  defaultCommandPaletteLabels,
  type CommandPaletteProps,
  type Row,
  defaultFilter,
  indexItems,
  buildSections,
  readStored,
  idSafe,
  useVisualViewportHeight,
} from "./parts/model";
import { ResultsPage, SearchIcon, EmptyState, type VirtualRow } from "./parts/parts";

export {
  type CommandItem,
  type CommandPaletteLabels,
  defaultCommandPaletteLabels,
  type CommandFilter,
  type CommandPaletteProps,
  highlightMatch,
} from "./parts/model";

/**
 * Command palette (Cmd/Ctrl+K): a glass dialog with a fuzzy search field over grouped commands.
 * Use it for "jump to anything" navigation and app-wide actions. Commands with `items` open a
 * nested page; recently used commands are listed first.
 *
 * Props: see {@link CommandPaletteProps} (`items` required, `open` / `defaultOpen` /
 * `onOpenChange`, `modal` true, `initialFocus` (the field), `container`, `trigger`, `shortcut` "mod+k", `onSelect`, `query` / `defaultQuery` /
 * `onQueryChange`, `filter`, `deepSearch` true, `maxResults` 100, `recent` / `onRecentChange` /
 * `recentStorageKey`, `maxRecent` 5, `loading`, `emptyState`, `footer`, `labels`, `shortcutLabels`,
 * `className`). Each {@link CommandItem} has `id`, `label`, `description`, `keywords`, `group`,
 * `icon`, `shortcut`, `hint`, `disabled`, `onSelect`, `keepOpen`, `items`.
 *
 * Long lists are windowed (`virtualized`, automatic above 200 results), so thousands of commands stay fast.
 *
 * Keyboard: Cmd/Ctrl+K toggles it from anywhere (`shortcut`). Up / Down (or Ctrl+N / Ctrl+P) move through results, Page Up / Down jump, Enter runs, Escape (or Backspace in an empty field) goes back a page and then closes.
 * Accessibility: With `modal={false}` the page stays interactive and focus is not trapped; use it for previews, never for a real palette. The field is an ARIA combobox that owns a listbox (`aria-activedescendant`), so focus never leaves the field; the result count is announced politely, usage instructions are read on open, and the dialog is named by `labels.title`. Shortcut hints expose `aria-keyshortcuts`.
 * Glass: One glass dialog (the standard overlay surface); rows are flat.
 * Motion: The active highlight glides between results and pages slide sideways; reduced motion uses fades only.
 *
 * @example
 * ```tsx
 * import { Button, CommandPalette, type CommandItem } from "@sheenui/theme";
 *
 * const commands: CommandItem[] = [
 *   { id: "home", label: "Go to dashboard", group: "Navigate", shortcut: "g d", onSelect: () => console.log("home") },
 *   { id: "theme", label: "Toggle theme", group: "Settings", keywords: ["dark", "light"] },
 * ];
 *
 * export const Palette = () => <CommandPalette items={commands} trigger={<Button variant="glass">Search…</Button>} />;
 * ```
 *
 * @see /overlays/command-palette
 */
export function CommandPalette({
  items,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  modal = true,
  initialFocus,
  container,
  trigger,
  shortcut = "mod+k",
  onSelect,
  query: queryProp,
  defaultQuery = "",
  onQueryChange,
  filter = defaultFilter,
  deepSearch = true,
  maxResults = 100,
  virtualized,
  recent: recentProp,
  onRecentChange,
  recentStorageKey,
  maxRecent = 5,
  loading = false,
  emptyState,
  footer,
  labels: labelsProp,
  shortcutLabels,
  className,
}: CommandPaletteProps) {
  const labels = { ...defaultCommandPaletteLabels, ...labelsProp };
  const reduced = useSheenReducedMotion();
  const platform = useShortcutPlatform();
  const id = useId();
  const listId = `${id}-list`;
  const instructionsId = `${id}-instructions`;
  const inputRef = useRef<HTMLInputElement>(null);

  /* ----- state (each part controlled or not) ----- */
  const [open, setOpen] = useControllable(openProp, defaultOpen, onOpenChange);
  const [innerQuery, setInnerQuery] = useState(defaultQuery);
  const query = queryProp ?? innerQuery;
  const [innerRecent, setInnerRecent] = useState<string[]>(() => readStored(recentStorageKey));
  const recent = recentProp ?? innerRecent;
  const [pages, setPages] = useState<CommandItem[]>([]);
  const [direction, setDirection] = useState<1 | -1>(1);
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const activeSource = useRef<"keyboard" | "pointer">("keyboard");

  function setQuery(next: string) {
    if (queryProp === undefined) setInnerQuery(next);
    onQueryChange?.(next);
    setActiveKey(null);
    activeSource.current = "keyboard";
  }

  // Each opening starts fresh at the top level (adjusting state during render, not in an effect,
  // so the first painted frame is already right).
  const [wasOpen, setWasOpen] = useState(open);
  if (open !== wasOpen) {
    setWasOpen(open);
    if (open) {
      setPages([]);
      setActiveKey(null);
      if (queryProp === undefined) setInnerQuery(defaultQuery);
    }
  }

  useCommandShortcut(() => setOpen(!open), { keys: shortcut || undefined, enabled: shortcut !== false });
  const viewportHeight = useVisualViewportHeight(open);

  /* ----- results ----- */
  const index = useMemo(() => indexItems(items), [items]);
  const page = pages.at(-1);
  const trimmed = query.trim();
  // Searching big lists runs at a lower priority, so typing never waits for results. An
  // emptied field (open, page change, cleared) shows its list straight away.
  const deferredQuery = useDeferredValue(query);
  const searchQuery = trimmed ? deferredQuery.trim() : "";
  const buildOptions = {
    items,
    pages,
    recent,
    index,
    maxRecent,
    recentLabel: labels.recent,
    filter,
    deepSearch,
    maxResults,
  };

  const recentLabel = labels.recent;
  const sections = useMemo(
    () =>
      buildSections({
        items,
        pages,
        recent,
        index,
        maxRecent,
        recentLabel,
        filter,
        deepSearch,
        maxResults,
        query: searchQuery,
      }),
    [searchQuery, items, pages, recent, index, maxRecent, recentLabel, filter, deepSearch, maxResults],
  );

  const rows = useMemo(() => sections.flatMap((s) => s.rows), [sections]);
  const enabledRows = rows.filter((r) => !r.item.disabled);
  const active = rows.find((r) => r.key === activeKey && !r.item.disabled) ?? enabledRows[0];
  // Ids follow the command, not its position: when the top result changes, so does the
  // active descendant, and screen readers announce the new one.
  const optionId = (row: Row) => `${id}-o-${idSafe(row.key)}`;
  const activeId = active ? optionId(active) : undefined;
  const reserveIcon = rows.some((r) => r.item.icon != null);

  /* ----- windowing: a long list renders only the rows near the viewport ----- */
  const virtual = shouldVirtualize(virtualized, rows.length);
  const hasDescriptions = virtual && rows.some((r) => r.item.description);
  const virtualRows = useMemo<VirtualRow[]>(() => {
    if (!virtual) return [];
    const out: VirtualRow[] = [];
    let position = 0;
    for (const section of sections) {
      if (section.heading) out.push({ kind: "heading", key: `h:${section.key}`, label: section.heading });
      for (const row of section.rows) out.push({ kind: "option", row, position: ++position, group: section.heading });
    }
    return out;
  }, [virtual, sections]);
  const {
    ref: listRef,
    element: listElement,
    scrollToIndex,
    start,
    end,
    size: rowSize,
  } = useVirtualWindow({
    count: virtualRows.length,
    enabled: virtual,
    estimateSize: hasDescriptions ? 56 : 44,
    overscan: 8,
    fallbackViewport: 360,
  });
  const activeAt = active ? virtualRows.findIndex((v) => v.kind === "option" && v.row === active) : -1;

  // Keep the highlighted result in view when it moved by keyboard.
  useLayoutEffect(() => {
    if (!activeId || activeSource.current !== "keyboard") return;
    if (virtual) {
      // The row may not exist yet: place the scroll position first, the window renders it with the next frame.
      if (activeAt >= 0) {
        if (virtualRows[activeAt - 1]?.kind === "heading") scrollToIndex(activeAt - 1, "nearest");
        scrollToIndex(activeAt, "nearest");
      }
      return;
    }
    document.getElementById(activeId)?.scrollIntoView({ block: "nearest" });
  }, [activeId, virtual, activeAt, virtualRows, scrollToIndex]);

  const windowedPage = virtual
    ? (() => {
        const visible: number[] = [];
        const pinned = activeAt >= 0 && (activeAt < start || activeAt >= end) ? activeAt : -1;
        if (pinned >= 0 && pinned < start) visible.push(pinned);
        for (let at = start; at < end; at++) visible.push(at);
        if (pinned > start) visible.push(pinned);
        return {
          rows: virtualRows,
          visible,
          size: rowSize,
          heightClass: hasDescriptions ? "h-14" : "h-11",
          total: rows.length,
        };
      })()
    : undefined;

  /* ----- announcements (debounced, so typing isn't drowned in chatter) ----- */
  const [announcement, setAnnouncement] = useState("");
  // Re-announce only when the results change: the wording (labels) is read when the timer fires.
  const announceResults = useEffectEvent(() => {
    if (!searchQuery) setAnnouncement("");
    else if (loading && rows.length === 0) setAnnouncement(labels.loading);
    else setAnnouncement(rows.length ? labels.results(enabledRows.length) : labels.noResults(searchQuery));
  });
  useEffect(() => {
    if (!open) return;
    const timer = window.setTimeout(announceResults, 450);
    return () => window.clearTimeout(timer);
  }, [open, searchQuery, rows.length, enabledRows.length, loading]);

  /* ----- actions ----- */
  function recordRecent(itemId: string) {
    if (maxRecent <= 0) return;
    const next = [itemId, ...recent.filter((r) => r !== itemId)].slice(0, maxRecent);
    if (recentProp === undefined) setInnerRecent(next);
    onRecentChange?.(next);
    if (recentStorageKey && recentProp === undefined) {
      try {
        window.localStorage.setItem(recentStorageKey, JSON.stringify(next));
      } catch {
        /* storage blocked: recents still work for this visit */
      }
    }
  }

  function goTo(stack: CommandItem[], dir: 1 | -1) {
    // Focus first: the Back button that may have been pressed is about to unmount.
    inputRef.current?.focus();
    setDirection(dir);
    setPages(stack);
    setQuery("");
  }

  function choose(row: Row) {
    const { item, path } = row;
    if (item.disabled) return;
    if (item.items) {
      goTo([...path, item], 1);
      return;
    }
    if (item.recordRecent !== false) recordRecent(item.id);
    item.onSelect?.(item);
    onSelect?.(item);
    if (!item.keepOpen) setOpen(false);
  }

  function move(step: number, wrap = true) {
    if (enabledRows.length === 0) return;
    const current = active ? enabledRows.indexOf(active) : -1;
    let next = current + step;
    if (wrap) next = (next + enabledRows.length) % enabledRows.length;
    else next = Math.max(0, Math.min(enabledRows.length - 1, next));
    activeSource.current = "keyboard";
    const target = enabledRows[next];
    if (target) setActiveKey(target.key);
  }

  /** Enter right after typing: if the results haven't caught up yet, rank the latest text now. */
  function chooseActive() {
    if (searchQuery === trimmed) {
      if (active) choose(active);
      return;
    }
    const fresh = buildSections({ ...buildOptions, query: trimmed }).flatMap((s) => s.rows);
    const target = fresh.find((r) => r.key === activeKey && !r.item.disabled) ?? fresh.find((r) => !r.item.disabled);
    if (target) choose(target);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    // keyCode 229: Safari sends the Enter that confirms an IME composition after compositionend.
    if (isImeComposing(event.nativeEvent)) return;
    const ctrlOnly = event.ctrlKey && !event.metaKey && !event.altKey;
    if (event.key === "ArrowDown" || (ctrlOnly && event.key === "n")) move(1);
    else if (event.key === "ArrowUp" || (ctrlOnly && event.key === "p")) move(-1);
    else if (event.key === "PageDown") move(pageSize(listElement, rowSize), false);
    else if (event.key === "PageUp") move(-pageSize(listElement, rowSize), false);
    else if (event.key === "Enter") chooseActive();
    else if (event.key === "Backspace" && query === "" && pages.length > 0) {
      goTo(pages.slice(0, -1), -1);
    } else return;
    event.preventDefault();
  }

  /* ----- motion ----- */
  const pageVariants: Variants = {
    enter: (dir: number) => ({ opacity: 0, x: reduced ? 0 : dir * 24 }),
    center: { opacity: 1, x: 0, transition: reduced ? { duration: duration.fast } : spring.snappy },
    exit: (dir: number) => ({ opacity: 0, x: reduced ? 0 : dir * -24, transition: exitTransition }),
  };
  const pageKey = pages.map((p) => p.id).join("/") || "root";
  const showFooter = footer !== false;
  const hasRows = rows.length > 0;

  const emptyContent =
    loading && rows.length === 0 ? (
      <p className="px-4 py-10 text-center text-sm text-sheen-fg-muted">{labels.loading}</p>
    ) : typeof emptyState === "function" ? (
      emptyState(searchQuery)
    ) : emptyState !== undefined ? (
      emptyState
    ) : (
      <EmptyState
        title={searchQuery ? labels.noResults(searchQuery) : labels.emptyList}
        hint={searchQuery ? labels.noResultsHint : undefined}
        reduced={reduced}
      />
    );

  const panelStyle = viewportHeight ? ({ "--sheen-command-vvh": `${viewportHeight}px` } as CSSProperties) : undefined;

  return (
    <Dialog
      open={open}
      modal={modal}
      onOpenChange={(next, details) => {
        // Escape on a nested page goes back a level instead of closing.
        if (!next && details.reason === "escape-key" && pages.length > 0) {
          details.cancel();
          goTo(pages.slice(0, -1), -1);
          return;
        }
        setOpen(next);
      }}
    >
      {trigger && <DialogTrigger render={trigger} />}
      <DialogContent
        showClose={false}
        initialFocus={initialFocus ?? inputRef}
        container={container}
        backdrop={modal}
        data-slot="command-palette"
        style={panelStyle}
        className={cn(
          // Anchored near the top (not centred) so the field stays put while results change. The
          // height follows the visible area, so the on-screen keyboard never covers results.
          "top-[max(1rem,10dvh)] w-[min(40rem,calc(100vw-2rem))] -translate-y-0",
          "max-h-[min(36rem,calc(min(100dvh,var(--sheen-command-vvh,100dvh))_-_max(1rem,10dvh)_-_1rem))]",
          "origin-[50%_0] gap-0 overflow-hidden p-0",
          className,
        )}
      >
        <DialogTitle className="sr-only">{labels.title}</DialogTitle>
        <p id={instructionsId} className="sr-only">
          {labels.instructions}
        </p>

        {/* ----- search row ----- */}
        <div className="group/search relative flex shrink-0 items-center gap-2 border-b border-sheen-border px-3 sm:px-4">
          {page ? (
            <button
              type="button"
              aria-label={labels.backButton(page.label, labels.back)}
              onClick={() => goTo(pages.slice(0, -1), -1)}
              className={cn(
                // Phones: an arrow only (the page name sits above the field). Wider: a chip with the name.
                "inline-flex h-8 min-w-8 shrink-0 items-center justify-center gap-1 rounded-sheen-full bg-sheen-accent-soft text-sm font-medium text-sheen-accent",
                "sm:max-w-[45%] sm:py-1 sm:pe-3 sm:ps-2",
                "shadow-[inset_0_0_0_1px_var(--sheen-accent-border)] transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover",
                "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
                "any-pointer-coarse:h-11 any-pointer-coarse:min-w-11 forced-colors:border forced-colors:border-[ButtonText]",
              )}
            >
              <svg
                aria-hidden
                viewBox="0 0 24 24"
                className="size-4 shrink-0 rtl:rotate-180"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="m15 6-6 6 6 6" />
              </svg>
              <span className="hidden truncate sm:inline">{page.label}</span>
            </button>
          ) : (
            <SearchIcon />
          )}
          <label className="flex min-w-0 flex-1 flex-col justify-center">
            {page && (
              <span
                aria-hidden
                className="truncate pt-1.5 text-2xs font-semibold tracking-[0.08em] text-sheen-fg-muted uppercase sm:hidden"
              >
                {page.label}
              </span>
            )}
            <input
              ref={inputRef}
              type="text"
              role="combobox"
              aria-label={page ? labels.pageInputLabel(page.label, labels.inputLabel) : labels.inputLabel}
              aria-describedby={instructionsId}
              aria-expanded={hasRows}
              aria-controls={hasRows ? listId : undefined}
              aria-activedescendant={activeId}
              aria-autocomplete="list"
              aria-busy={loading || undefined}
              autoComplete="off"
              autoCorrect="off"
              autoCapitalize="none"
              spellCheck={false}
              enterKeyHint="go"
              value={query}
              placeholder={page?.placeholder ?? labels.placeholder}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyDown}
              className={cn(
                "h-14 min-w-0 bg-transparent text-base text-sheen-fg outline-none placeholder:text-sheen-fg-subtle [&::-webkit-search-cancel-button]:hidden",
                page && "max-sm:h-8.5",
                // High contrast: the underline below is the focus indicator (a box would be clipped by the panel).
                "forced-colors:outline-none!",
                // The field's own indicator is the underline below; Aurora's double-ring box-shadow on inputs would draw a hard square inside the rounded panel.
                "focus-visible:shadow-none!",
              )}
            />
          </label>
          {/* Solid focus indicator under the field: grows from the centre when it gains focus. */}
          <span
            aria-hidden
            className={cn(
              "pointer-events-none absolute inset-x-0 -bottom-px h-0.5 origin-center scale-x-0 bg-sheen-focus opacity-0",
              "transition-[opacity,scale] duration-(--sheen-duration-slow) ease-sheen-out",
              "group-has-[input:focus-visible]/search:scale-x-100 group-has-[input:focus-visible]/search:opacity-100",
              "forced-colors:bg-[Highlight] forced-colors:forced-color-adjust-none",
            )}
          />
          {loading && <SpinnerIcon className="size-4 shrink-0 text-sheen-fg-muted" />}
          <DialogClose
            className={cn(
              "inline-flex shrink-0 items-center justify-center rounded-sheen-sm text-sheen-fg-muted transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover hover:text-sheen-fg",
              "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
              "h-8 px-1 any-pointer-coarse:h-11 any-pointer-coarse:min-w-11",
            )}
          >
            {/* Fine pointers see the Esc key cap; touch screens get a × (there's no Escape key). */}
            <Kbd aria-hidden className="pointer-coarse:hidden">
              Esc
            </Kbd>
            <svg
              aria-hidden
              viewBox="0 0 24 24"
              className="hidden size-5 pointer-coarse:block"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            >
              <path d="M6 6l12 12M18 6L6 18" />
            </svg>
            <span className="sr-only">{labels.close}</span>
          </DialogClose>
        </div>

        {/* ----- results: the scroll container is the listbox itself ----- */}
        <motion.div
          layoutScroll
          ref={listRef}
          id={hasRows ? listId : undefined}
          role={hasRows ? "listbox" : undefined}
          aria-label={hasRows ? (page ? page.label : labels.title) : undefined}
          // Keys stay in the search field (aria-activedescendant), so the list is no Tab stop; a
          // click on its padding hands focus straight back to the field.
          tabIndex={-1}
          onFocus={(e) => {
            if (e.target === e.currentTarget) inputRef.current?.focus();
          }}
          className="relative min-h-0 flex-1 scroll-py-2 overflow-y-auto overscroll-contain outline-none [scrollbar-width:thin]"
        >
          {/* popLayout: the next page is on screen (and its options exist) the moment it is chosen. */}
          <AnimatePresence mode="popLayout" initial={false} custom={direction}>
            <motion.div
              key={pageKey}
              role="presentation"
              custom={direction}
              variants={pageVariants}
              initial="enter"
              animate="center"
              exit="exit"
            >
              <ResultsPage
                sections={sections}
                active={active}
                optionId={optionId}
                headingId={(i) => `${id}-h-${i}`}
                layoutId={reduced ? undefined : `${id}-active-${pageKey}`}
                reserveIcon={reserveIcon}
                labels={labels}
                platform={platform}
                shortcutLabels={shortcutLabels}
                onHover={(row) => {
                  if (row === active || row.item.disabled) return;
                  activeSource.current = "pointer";
                  setActiveKey(row.key);
                }}
                onChoose={choose}
                empty={emptyContent}
                windowed={windowedPage}
              />
            </motion.div>
          </AnimatePresence>
        </motion.div>

        {/* ----- footer: key hints for keyboard users (hidden on touch screens) ----- */}
        {showFooter && (
          <div
            aria-hidden
            className="hidden shrink-0 items-center gap-4 border-t border-sheen-border px-4 py-2.5 text-xs text-sheen-fg-muted sm:flex pointer-coarse:hidden"
          >
            <span className="inline-flex items-center gap-1.5">
              <KbdShortcut keys="arrowup" announce={false} labels={shortcutLabels} />
              <KbdShortcut keys="arrowdown" announce={false} labels={shortcutLabels} />
              {labels.navigate}
            </span>
            <span className="inline-flex items-center gap-1.5">
              <Kbd>↵</Kbd>
              {labels.select}
            </span>
            <span className="inline-flex items-center gap-1.5">
              <Kbd>Esc</Kbd>
              {page ? labels.back : labels.close}
            </span>
            {footer != null && <span className="ms-auto inline-flex min-w-0 items-center gap-2">{footer}</span>}
          </div>
        )}

        <div role="status" aria-live="polite" aria-atomic className="sr-only">
          {announcement}
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Fuzzy matching for the command palette (no dependencies).
 *
 * The query's letters must appear in order in the text, not necessarily together:
 * "nwtb" finds "New tab". Among all the ways the letters could line up, the best one wins
 * (dynamic programming, like fzf): runs of consecutive letters and letters at the start of
 * a word ("New Tab", "dark-mode", "camelCase") score high; gaps cost a little.
 *
 * Case, accents and spaces in the query are ignored ("cafe" finds "Café").
 * `indices` are UTF-16 offsets into the ORIGINAL text, ready for highlighting.
 *
 * Speed: each text is analysed once (`prepareText`) and reused for every keystroke. Pass a
 * prepared text when you keep many commands around; plain strings go through an LRU cache.
 */

export type FuzzyMatch = {
  /** Higher is better. Only meaningful for comparing matches of the same query. */
  score: number;
  /** Offsets (into the original text) of the characters that matched. */
  indices: number[];
};

const MATCH = 16;
const CONSECUTIVE = 8;
const GAP_START = 3;
const GAP_EXTEND = 1;
const BONUS_FIRST = 10;
const BONUS_WORD = 9;
const BONUS_CAMEL = 7;
const BONUS_DIGIT = 4;
const BONUS_PREFIX = 24;
const BONUS_SUBSTRING = 12;
const BONUS_EXACT = 60;

const SEPARATOR = /[\s\-_/\\.,:;|()[\]{}<>"'`·•&+@#]/;

/** A text analysed for matching: build it once with prepareText() and match it many times. */
export type PreparedText = {
  /** The original text. */
  readonly text: string;
  /** Normalised (lower-case, accent-free) characters. */
  readonly chars: readonly string[];
  /** The normalised characters joined, for exact / prefix / substring checks. */
  readonly flat: string;
  /** Offset in the original string of the character each normalised one came from. */
  readonly origin: Int32Array;
  /** Position bonus of each normalised character (word starts, camelCase...). */
  readonly bonus: Uint8Array;
};

function normalizeChar(ch: string) {
  return ch.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
}

/** Lower-case, strip accents. Exported so custom filters can match the same way. */
export function normalizeText(text: string) {
  return text.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
}

function analyse(text: string): PreparedText {
  const chars: string[] = [];
  const origin: number[] = [];
  const bonus: number[] = [];
  let offset = 0;
  let prev = "";
  for (const ch of text) {
    const norm = normalizeChar(ch);
    let b = 0;
    if (offset === 0) b = BONUS_FIRST;
    else if (SEPARATOR.test(prev)) b = BONUS_WORD;
    else if (/\p{Ll}/u.test(prev) && /\p{Lu}/u.test(ch)) b = BONUS_CAMEL;
    else if (/\p{L}/u.test(prev) !== /\p{L}/u.test(ch) && /\p{N}/u.test(prev + ch)) b = BONUS_DIGIT;
    let first = true;
    for (const n of norm) {
      chars.push(n);
      origin.push(offset);
      bonus.push(first ? b : 0);
      first = false;
    }
    prev = ch;
    offset += ch.length;
  }
  return { text, chars, flat: chars.join(""), origin: Int32Array.from(origin), bonus: Uint8Array.from(bonus) };
}

/*
 * Plain strings: a least-recently-used cache, so labels aren't re-analysed on every keystroke.
 * A hit moves the entry to the back; past the limit the oldest quarter goes.
 */
const CACHE_LIMIT = 8000;
const cache = new Map<string, PreparedText>();

/**
 * Analyse a text once so it can be matched against many queries cheaply. Keep the result
 * next to your data (e.g. per command) and pass it to fuzzyMatch / matchCommand.
 */
export function prepareText(text: string): PreparedText {
  const hit = cache.get(text);
  if (hit) {
    cache.delete(text);
    cache.set(text, hit);
    return hit;
  }
  const next = analyse(text);
  cache.set(text, next);
  if (cache.size > CACHE_LIMIT) {
    let drop = CACHE_LIMIT / 4;
    for (const key of cache.keys()) {
      cache.delete(key);
      if (--drop <= 0) break;
    }
  }
  return next;
}

function prepared(text: string | PreparedText): PreparedText {
  return typeof text === "string" ? prepareText(text) : text;
}

/* The same query is matched against every command: normalise it once. */
let lastQuery: { raw: string; flat: string; chars: string[] } = { raw: "", flat: "", chars: [] };

function preparedQuery(query: string) {
  if (query !== lastQuery.raw) {
    const flat = normalizeText(query).trim();
    lastQuery = { raw: query, flat, chars: Array.from(flat.replace(/\s+/g, "")) };
  }
  return lastQuery;
}

/** Fuzzy-match `query` against `text`. Returns null when the letters don't all appear in order. */
export function fuzzyMatch(text: string | PreparedText, query: string): FuzzyMatch | null {
  const { flat: rawQuery, chars: q } = preparedQuery(query);
  if (q.length === 0) return { score: 0, indices: [] };

  const { chars, origin, bonus, flat } = prepared(text);
  const n = chars.length;
  const m = q.length;
  if (m > n) return null;

  // Cheap rejection: is the query a subsequence at all?
  for (let i = 0, j = 0; i < m; j++) {
    if (j >= n) return null;
    if (chars[j] === q[i]) i++;
  }

  // best[i*n + j]: best score with q[i] matched at text[j].
  // carry[i*n + j]: best score with q[0..i] matched at or before j, gap costs paid up to j.
  const NEG = -Infinity;
  const best = new Float64Array(m * n).fill(NEG);
  const carry = new Float64Array(m * n).fill(NEG);
  const fromRun = new Uint8Array(m * n); // best came from the previous letter right before it
  const carryFromBest = new Uint8Array(m * n); // carry came from best at the same cell

  for (let i = 0; i < m; i++) {
    const qc = q[i];
    for (let j = 0; j < n; j++) {
      const cell = i * n + j;
      if (chars[j] === qc) {
        const base = MATCH + (bonus[j] ?? 0);
        if (i === 0) {
          // A small nudge towards matches that start early in the text.
          best[cell] = base - Math.min(j, 12) * 0.25;
        } else if (j > 0) {
          const prev = (i - 1) * n + j - 1;
          const run = (best[prev] ?? NEG) + CONSECUTIVE;
          const jump = carry[prev] ?? NEG;
          if (run >= jump && run > NEG) {
            best[cell] = run + base;
            fromRun[cell] = 1;
          } else if (jump > NEG) {
            best[cell] = jump + base;
          }
        }
      }
      const stay = (best[cell] ?? NEG) - GAP_START;
      const extend = j > 0 ? (carry[cell - 1] ?? NEG) - GAP_EXTEND : NEG;
      if (stay >= extend) {
        carry[cell] = stay;
        carryFromBest[cell] = 1;
      } else {
        carry[cell] = extend;
      }
    }
  }

  let end = -1;
  let score = NEG;
  const last = (m - 1) * n;
  for (let j = 0; j < n; j++) {
    const value = best[last + j] ?? NEG;
    if (value > score) {
      score = value;
      end = j;
    }
  }
  if (end < 0 || score === NEG) return null;

  // Walk back through the choices to find which characters matched.
  const matched: number[] = [];
  let i = m - 1;
  let j = end;
  while (i >= 0 && j >= 0) {
    matched.push(j);
    if (i === 0) break;
    const cell = i * n + j;
    i -= 1;
    j -= 1;
    if (fromRun[cell]) continue;
    // Follow the carried gap back to where letter i was actually matched.
    while (j > 0 && !carryFromBest[i * n + j]) j -= 1;
  }
  matched.reverse();

  if (flat === rawQuery) score += BONUS_EXACT;
  else if (flat.startsWith(rawQuery)) score += BONUS_PREFIX;
  else if (flat.includes(rawQuery)) score += BONUS_SUBSTRING;

  // Several normalised characters can come from one original (rare): report each once.
  const indices = [...new Set(matched.flatMap((k) => origin[k] ?? []))];
  return { score, indices };
}

/** Best match of a query against a label and its extra search words. Keyword hits don't highlight. */
export function matchCommand(
  query: string,
  label: string | PreparedText,
  extra: readonly (string | PreparedText | undefined)[] = [],
): FuzzyMatch | null {
  const direct = fuzzyMatch(label, query);
  let bestExtra: FuzzyMatch | null = null;
  for (const text of extra) {
    if (!text) continue;
    const hit = fuzzyMatch(text, query);
    if (hit && (!bestExtra || hit.score > bestExtra.score)) bestExtra = hit;
  }
  if (bestExtra) {
    const weighted = { score: bestExtra.score * 0.75, indices: [] };
    if (!direct || weighted.score > direct.score) return weighted;
  }
  return direct;
}

"use client";

import { useEffect, useState, type ReactElement, type ReactNode } from "react";

import type { DialogContentProps } from "../../dialog/dialog";
import { type KbdLabels } from "../../kbd/shortcut";
import { matchCommand, prepareText, type FuzzyMatch, type PreparedText } from "../fuzzy";

/**
 * Command palette (⌘K): a glass dialog with a search field over grouped commands.
 *
 *   <CommandPalette items={commands} trigger={<Button variant="glass">Search…</Button>} />
 *
 * - Fuzzy search with the matched letters highlighted; results are ranked, best group first.
 * - ↑ ↓ (or Ctrl+N / Ctrl+P) move, Enter runs, Escape closes. PageUp / PageDown jump.
 * - Commands with `items` open a nested page; Escape or Backspace (empty field) goes back.
 *   From the top level, search also finds commands inside pages (`deepSearch`).
 * - Recently used commands are listed first (kept in memory, in localStorage with
 *   `recentStorageKey`, or controlled with `recent` / `onRecentChange`).
 * - ⌘K / Ctrl+K toggles it from anywhere (`shortcut`).
 *
 * Accessibility: the field is a combobox that owns a listbox (aria-activedescendant), so
 * focus never leaves the field; the result count is announced politely. Motion: the
 * highlight glides between results and pages slide sideways; reduced motion: fades only.
 */

/** One command (or a group of sub-commands) in a {@link CommandPalette}. */
export type CommandItem = {
  /** Unique across the whole tree (used for recents and keys). */
  id: string;
  /** The command's name. Searched, and highlighted where it matches. */
  label: string;
  /** Shows the second line under the label. Also searched. */
  description?: string;
  /** Extra words that find this command but aren't shown, e.g. ["preferences", "config"]. */
  keywords?: readonly string[];
  /** Heading the command is listed under. */
  group?: string;
  /** Icon before the label. */
  icon?: ReactNode;
  /** Shortcut to show, e.g. "mod+shift+l". Displayed only: bind it yourself. Hidden on phones. */
  shortcut?: string | readonly string[];
  /** Short text or a badge at the end of the row, e.g. "Jump to" or "3 new". Shown on every screen size. */
  hint?: ReactNode;
  /** Show the command but make it unselectable. */
  disabled?: boolean;
  /** Runs when the command is chosen. */
  onSelect?: (item: CommandItem) => void;
  /** Keep the palette open after running (e.g. toggles). */
  keepOpen?: boolean;
  /** Sub-commands: choosing this command opens them as a nested page. */
  items?: readonly CommandItem[];
  /** Search placeholder on this command's nested page. */
  placeholder?: string;
  /**
   * List it under "Recent" after use.
   * @default true
   */
  recordRecent?: boolean;
};

/** Every UI string of {@link CommandPalette}; pass a partial through its `labels` prop to translate it. */
export type CommandPaletteLabels = {
  /** Name of the dialog (read by screen readers, not shown). */
  title: string;
  /** Name of the search field. */
  inputLabel: string;
  /** Name of the search field on a nested page. Gets the page's label and `inputLabel`. */
  pageInputLabel: (page: string, inputLabel: string) => string;
  /** Placeholder of the search field. */
  placeholder: string;
  /** Heading of the recently used group. */
  recent: string;
  /** Heading of the empty state, and what is announced. */
  noResults: (query: string) => string;
  /** Hint under the empty-state heading. */
  noResultsHint: ReactNode;
  /** Shown when there are no commands at all. */
  emptyList: string;
  /** Shown while `loading` is true and there are no results yet. */
  loading: string;
  /** Announced as the results change. */
  results: (count: number) => string;
  /** Footer hint for Escape on a nested page. */
  back: string;
  /** Name of the back button on a nested page. Gets the page's label and `back`. */
  backButton: (page: string, back: string) => string;
  /** Name of the close button. */
  close: string;
  /** Footer hint for the arrow keys. */
  navigate: string;
  /** Footer hint for Enter. */
  select: string;
  /** Spoken name of a command that opens a nested page. Gets the command's label. */
  opensPage: (label: string) => string;
  /** Read to screen readers on open: how to use the palette. */
  instructions: string;
};

/** The English strings of {@link CommandPalette}. Spread it to build your own set. */
export const defaultCommandPaletteLabels: CommandPaletteLabels = {
  title: "Command palette",
  inputLabel: "Search commands",
  pageInputLabel: (page, inputLabel) => `${inputLabel}: ${page}`,
  placeholder: "Search or jump to…",
  recent: "Recent",
  noResults: (query) => `No results for “${query}”`,
  noResultsHint: "Try a shorter word or check the spelling.",
  emptyList: "No commands yet.",
  loading: "Searching…",
  results: (count) => (count === 1 ? "1 result" : `${count} results`),
  back: "Back",
  backButton: (page, back) => `${back}: ${page}`,
  close: "Close",
  navigate: "Navigate",
  select: "Select",
  opensPage: (label) => `${label}, opens more options`,
  instructions:
    "Type to search. Use the up and down arrow keys to move through results, Enter to run one, Escape to go back or close.",
};

/** A custom matcher for {@link CommandPalette}'s `filter`: return a match (with the highlighted ranges) or `null` to hide the command. */
export type CommandFilter = (item: CommandItem, query: string) => FuzzyMatch | null;

/** Props of {@link CommandPalette}. */
export type CommandPaletteProps = {
  /** The commands. Order is kept when the search field is empty. */
  items: readonly CommandItem[];
  /** Whether the palette is open (controlled). */
  open?: boolean;
  /**
   * Whether it starts open (uncontrolled).
   * @default false
   */
  defaultOpen?: boolean;
  /** Called with the new state when the palette opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /**
   * Whether the rest of the page is blocked while it is open (Base UI dialog semantics). `false` leaves the page
   * interactive, drops the scrim and does not trap focus: for previews and demos that open on their own.
   * @default true
   */
  modal?: boolean;
  /**
   * Where focus lands when it opens: an element, a ref, or a function (Base UI's `initialFocus`). `false` moves
   * focus nowhere, so a palette that opens by itself never steals it.
   * @default the search field
   */
  initialFocus?: DialogContentProps["initialFocus"];
  /**
   * Where the palette is portalled. Pass an element to keep it inside a region instead of the end of the body.
   * @default the end of document.body
   */
  container?: DialogContentProps["container"];
  /** Rendered as the button that opens the palette (focus returns to it on close). */
  trigger?: ReactElement;
  /**
   * Global shortcut that toggles the palette. `false` to register none.
   * @default "mod+k"
   */
  shortcut?: string | false;
  /** Called after any command runs (besides its own onSelect). */
  onSelect?: (item: CommandItem) => void;
  /** Sets the search text when controlled. */
  query?: string;
  /** The search text on mount (uncontrolled). */
  defaultQuery?: string;
  /** Called with the search text as it changes (fetch your own results here). */
  onQueryChange?: (query: string) => void;
  /**
   * How results are matched. Default: fuzzy match on label, description and keywords.
   * Pass a function to match your way, or `false` to show `items` as given (e.g. results
   * you fetched yourself in onQueryChange); matches are still highlighted.
   */
  filter?: CommandFilter | false;
  /**
   * From the top level, also search commands inside nested pages.
   * @default true
   */
  deepSearch?: boolean;
  /**
   * Most results listed while searching (the best ones). Keeps typing quick with thousands of commands.
   * @default 100
   */
  maxResults?: number;
  /**
   * Windows the result list so only the rows near the viewport are in the DOM: `true` always, `false` never, `"auto"`
   * only above 200 results (a long list with no query, or a large `maxResults`). The active command, the keyboard keys
   * (`aria-activedescendant` stays on the search field), `aria-setsize` / `aria-posinset` and the scroll height work
   * across every result. Windowed rows are a fixed height (a `description` is cut to fit) and the group headings are
   * visual only.
   *
   * @default "auto"
   */
  virtualized?: boolean | "auto";
  /** Lists the ids of recent commands, newest first, when controlled. */
  recent?: readonly string[];
  /** Called with the new list of recent ids after a command runs. */
  onRecentChange?: (ids: string[]) => void;
  /** Remember recents in localStorage under this key (uncontrolled). */
  recentStorageKey?: string;
  /**
   * How many recents to keep. 0 turns the Recent group off.
   * @default 5
   */
  maxRecent?: number;
  /**
   * Shows a spinner in the field (and "Searching…" while there are no results yet).
   * @default false
   */
  loading?: boolean;
  /** Replaces the empty state. Gets the query. */
  emptyState?: ReactNode | ((query: string) => ReactNode);
  /** Extra content at the end of the key-hint footer, or `false` to hide the footer. Hidden on touch screens. */
  footer?: ReactNode;
  /** Every string, for translation. */
  labels?: Partial<CommandPaletteLabels>;
  /** Key names in the shortcut hints (i18n). */
  shortcutLabels?: Partial<KbdLabels>;
  /** Adds extra classes to the dialog panel. */
  className?: string;
};

/** One result row: a command with the pages leading to it and its fuzzy match. @internal */
export type Row = {
  key: string;
  item: CommandItem;
  /** Pages leading to this command (from the top level). */
  path: CommandItem[];
  match: FuzzyMatch | null;
};

/** One result section with its heading and rows. @internal */
export type Section = { key: string; heading: string; rows: Row[] };

/** A searchable item with its ancestor path. @internal */
export type IndexEntry = { item: CommandItem; path: CommandItem[] };

/* ---------- matching ---------- */

/* Each command's searchable texts, analysed once per command object (not per keystroke). */
/** A command's searchable texts, analysed once per command object. @internal */
export type PreparedItem = {
  label: PreparedText;
  extra: PreparedText[];
  description?: string;
  keywords?: readonly string[];
};
/** A cache of prepared search text per item. @internal */
export const preparedItems = new WeakMap<CommandItem, PreparedItem>();

/** Normalises an item's searchable text once and caches it. @internal */
export function prepareItem(item: CommandItem): PreparedItem {
  const hit = preparedItems.get(item);
  if (hit?.label.text === item.label && hit.description === item.description && hit.keywords === item.keywords)
    return hit;
  const extra = [item.description, ...(item.keywords ?? [])].filter((t): t is string => Boolean(t)).map(prepareText);
  const next = { label: prepareText(item.label), extra, description: item.description, keywords: item.keywords };
  preparedItems.set(item, next);
  return next;
}

/** The default filter: a fuzzy match of the query against an item's label and extra search terms. @internal */
export const defaultFilter: CommandFilter = (item, query) => {
  const { label, extra } = prepareItem(item);
  return matchCommand(query, label, extra);
};

/** Every command in the tree with the pages above it. */
export function indexItems(
  items: readonly CommandItem[],
  path: CommandItem[] = [],
  into = new Map<string, IndexEntry>(),
) {
  for (const item of items) {
    into.set(item.id, { item, path });
    if (item.items) indexItems(item.items, [...path, item], into);
  }
  return into;
}

/** Rows in order → sections in order of their first row. */
export function groupRows(rows: Row[], heading: (row: Row) => string, prefix: string): Section[] {
  const sections = new Map<string, Section>();
  for (const row of rows) {
    const h = heading(row);
    let section = sections.get(h);
    if (!section) {
      section = { key: `${prefix}${h}`, heading: h, rows: [] };
      sections.set(h, section);
    }
    section.rows.push(row);
  }
  return [...sections.values()];
}

/** The options of `buildSections`. @internal */
export type BuildOptions = {
  /** Trimmed search text. */
  query: string;
  items: readonly CommandItem[];
  pages: CommandItem[];
  recent: readonly string[];
  index: Map<string, IndexEntry>;
  maxRecent: number;
  recentLabel: string;
  filter: CommandFilter | false;
  deepSearch: boolean;
  maxResults: number;
};

/** Builds the grouped, filtered, ordered result sections for a query. @internal */
export function buildSections({
  query,
  items,
  pages,
  recent,
  index,
  maxRecent,
  recentLabel,
  filter,
  deepSearch,
  maxResults,
}: BuildOptions): Section[] {
  const page = pages.at(-1);
  const pageItems = page?.items ?? items;

  if (!query) {
    const out: Section[] = [];
    if (!page && maxRecent > 0) {
      const recentRows = recent
        .map((rid) => index.get(rid))
        .filter((hit): hit is IndexEntry => Boolean(hit && !hit.item.disabled))
        .slice(0, maxRecent)
        .map(({ item, path }) => ({ key: `recent:${item.id}`, item, path, match: null }));
      if (recentRows.length) out.push({ key: "recent", heading: recentLabel, rows: recentRows });
    }
    const rows = pageItems.map((item) => ({ key: item.id, item, path: pages, match: null }));
    return [...out, ...groupRows(rows, (r) => r.item.group ?? "", "g:")];
  }

  // Candidates: this page, plus (at the top level) everything nested below it.
  const candidates: Row[] = [];
  const collect = (list: readonly CommandItem[], path: CommandItem[]) => {
    for (const item of list) {
      candidates.push({
        key: path.length > pages.length ? `${path.map((p) => p.id).join("/")}/${item.id}` : item.id,
        item,
        path,
        match: null,
      });
      if (item.items && !page && deepSearch) collect(item.items, [...path, item]);
    }
  };
  collect(pageItems, pages);

  if (filter === false) {
    const rows = candidates
      .filter((r) => r.path.length === pages.length)
      .map((r) => ({ ...r, match: defaultFilter(r.item, query) }));
    return groupRows(rows, (r) => r.item.group ?? "", "g:");
  }

  // Best first (a stable sort keeps the given order for ties), then grouped: each group
  // lands where its best result ranks. Nested results are listed under their page's name.
  const scored = candidates
    .map((r) => ({ ...r, match: filter(r.item, query) }))
    .filter((r): r is Row & { match: FuzzyMatch } => r.match !== null)
    .sort((a, b) => b.match.score - a.match.score)
    .slice(0, Math.max(1, maxResults));
  const heading = (r: Row) =>
    r.path.length > pages.length
      ? r.path
          .slice(pages.length)
          .map((p) => p.label)
          .join(" › ")
      : (r.item.group ?? "");
  return groupRows(scored, heading, "s:");
}

/* ---------- helpers ---------- */

/** Reads a string list from localStorage, returning an empty list when it is missing or invalid. @internal */
export function readStored(key: string | undefined): string[] {
  if (!key || typeof window === "undefined") return [];
  try {
    const parsed: unknown = JSON.parse(window.localStorage.getItem(key) ?? "[]");
    return Array.isArray(parsed) ? parsed.filter((v): v is string => typeof v === "string") : [];
  } catch {
    return [];
  }
}

/** Command ids can hold any text; DOM ids built from them must not (spaces split ID lists). */
export function idSafe(key: string) {
  return key.replace(/[^A-Za-z0-9-]/g, (ch) => `_${(ch.codePointAt(0) ?? 0).toString(16)}_`);
}

/**
 * Height of the visible area while the palette is open. On phones the on-screen keyboard
 * covers the bottom of the page without changing 100dvh; the visual viewport shrinks.
 */
export function useVisualViewportHeight(active: boolean) {
  const [height, setHeight] = useState<number | null>(null);
  useEffect(() => {
    const vv = typeof window === "undefined" ? undefined : window.visualViewport;
    if (!active || !vv) return;
    // Pinch zoom also shrinks the visual viewport: only follow it at normal scale.
    const update = () => setHeight(vv.scale <= 1.01 ? vv.height : null);
    update();
    vv.addEventListener("resize", update);
    return () => vv.removeEventListener("resize", update);
  }, [active]);
  return active ? height : null;
}

/** Wrap the matched characters in <mark>.
 *
 * @see /overlays/command-palette
 */
export function highlightMatch(text: string, indices: readonly number[]): ReactNode {
  if (indices.length === 0) return text;
  const hits = new Set(indices);
  const parts: ReactNode[] = [];
  let run = "";
  let runIsHit = false;
  let offset = 0;
  const flush = () => {
    if (!run) return;
    parts.push(
      runIsHit ? (
        <mark
          key={parts.length}
          className="bg-transparent font-[inherit] text-sheen-accent forced-colors:text-[CanvasText] forced-colors:underline"
        >
          {run}
        </mark>
      ) : (
        run
      ),
    );
    run = "";
  };
  for (const ch of text) {
    const hit = hits.has(offset);
    if (hit !== runIsHit) {
      flush();
      runIsHit = hit;
    }
    run += ch;
    offset += ch.length;
  }
  flush();
  return parts;
}

