/** The props of one page of results. @internal */
export type ResultsPageProps = {
  sections: Section[];
  active: Row | undefined;
  optionId: (row: Row) => string;
  headingId: (index: number) => string;
  layoutId: string | undefined;
  reserveIcon: boolean;
